    id character varying(250) NOT NULL,
    internal_code character varying(50),
    company_id bigint,
    legal_entity_id bigint,
    customer_id character varying(100),
    invoice_id character varying(200),
    amount numeric(15,2),
    adjustment_id character varying(50),
    adjustment_code character varying(50),
    adjustment_desc character varying(300),
    adjustment_effect character varying(15),
    source character varying(50),
    currency_type character varying(20),
    created_date timestamp without time zone,
    last_update timestamp without time zone,
    delete_flag character varying(10),
    archived character varying(10)
);


--
-- Name: TABLE erp_inv_adjustments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.erp_inv_adjustments IS 'Records credit and debit adjustments applied to invoices in accounts receivable. Each row captures the adjustment amount, code, description, and effect, supporting adjustment and reconciliation reporting. Notes: Adjustment header; line detail in erp_inv_adjustments_item. id is composite: <internal_code>#<invoice_id> (internal_code like SVIC...). adjustment_effect DR/CR; adjustment_code sample WALAMTADJ, CLAIMADJ; source sample ERP_LOAD, CLAIM; currency USD. amount DOUBLE in DDL; treat as DECIMAL (can be 0). Active = delete_flag=''NO'' AND archived=''NO''.';


--
-- Name: COLUMN erp_inv_adjustments.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.id IS 'Composite primary key: <internal_code>#<invoice_id> (e.g. SVIC...#INV...#529#1033). Source type: VARCHAR(250). Category: composite reference.';


--
-- Name: COLUMN erp_inv_adjustments.internal_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.internal_code IS 'Internal adjustment code (e.g. SVIC...). Source type: VARCHAR(50). Category: identifier.';


--
-- Name: COLUMN erp_inv_adjustments.company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.company_id IS 'Company isolation key. Scope by company_id = @company_id. Source type: BIGINT UNSIGNED. Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments.legal_entity_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.legal_entity_id IS 'Legal entity identifier. Joins to d_legalentity.id. Source type: BIGINT UNSIGNED. Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments.customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.customer_id IS 'Composite customer id. Scope by customer_id = @customer_id. Joins to erp_customer_details.id. Source type: VARCHAR(100). Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments.invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.invoice_id IS 'Composite invoice id. Joins to erp_invoice_details.id. Source type: VARCHAR(200). Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.amount IS 'Adjustment amount (DOUBLE in DDL; can be 0). Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_adjustments.adjustment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.adjustment_id IS 'Business identifier of the adjustment (e.g. SVADJ...; utf8mb4). Source type: VARCHAR(50). Category: identifier.';


--
-- Name: COLUMN erp_inv_adjustments.adjustment_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.adjustment_code IS 'Coded type. Sample: WALAMTADJ, CLAIMADJ. Source type: VARCHAR(50). Category: dimension.';


--
-- Name: COLUMN erp_inv_adjustments.adjustment_desc; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.adjustment_desc IS 'Description of the adjustment. Source type: VARCHAR(300). Category: free text.';


--
-- Name: COLUMN erp_inv_adjustments.adjustment_effect; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.adjustment_effect IS 'Effect: DR (debit) or CR (credit). Source type: VARCHAR(15). Category: dimension.';


--
-- Name: COLUMN erp_inv_adjustments.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.source IS 'Source. Sample: ERP_LOAD, CLAIM. Source type: VARCHAR(50). Category: dimension.';


--
-- Name: COLUMN erp_inv_adjustments.currency_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.currency_type IS 'Currency. Sample: USD. Source type: VARCHAR(20). Category: dimension.';


--
-- Name: COLUMN erp_inv_adjustments.created_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.created_date IS 'Record creation date. Source type: DATETIME. Category: timestamp.';


--
-- Name: COLUMN erp_inv_adjustments.last_update; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.last_update IS 'Timestamp of the most recent update. Source type: DATETIME. Category: audit.';


--
-- Name: COLUMN erp_inv_adjustments.delete_flag; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.delete_flag IS 'Soft delete flag. Use delete_flag = ''NO'' for active records. Source type: VARCHAR(10). Category: flag/boolean.';


--
-- Name: COLUMN erp_inv_adjustments.archived; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments.archived IS 'Archive flag. Use archived = ''NO'' for active records. Source type: VARCHAR(10). Category: flag/boolean.';


