CREATE TABLE public.erp_inv_adjustments_item (
    id bigint NOT NULL,
    invoice_id character varying(200),
    invoice_item_id character varying(250),
    inv_adj_id character varying(250),
    item_price numeric(15,2),
    adj_amount numeric(15,2),
    approved_amount numeric(15,2),
    quantity numeric(12,2),
    approved_quantity numeric(12,2),
    adj_on character varying(100),
    reason_category_id character varying(100),
    reason_sub_category_id character varying(100),
    last_update timestamp without time zone,
    integrated_tax numeric(15,2),
    state_tax numeric(15,2),
