COMMENT ON COLUMN public.erp_inv_adjustments_item.inv_adj_id IS 'Parent adjustment header. Joins to erp_inv_adjustments.id. Source type: VARCHAR(250). Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments_item.item_price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.item_price IS 'Unit/line price of the adjusted item (NULL in sample). Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_adjustments_item.adj_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.adj_amount IS 'Adjusted amount for the line. Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_adjustments_item.approved_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.approved_amount IS 'Approved adjustment amount. Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_adjustments_item.quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.quantity IS 'Quantity adjusted. Source type: DECIMAL(12,2). Category: measure / count.';


--
-- Name: COLUMN erp_inv_adjustments_item.approved_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.approved_quantity IS 'Quantity approved for adjustment. Source type: DECIMAL(12,2). Category: measure / count.';


--
-- Name: COLUMN erp_inv_adjustments_item.adj_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.adj_on IS 'Basis the adjustment is applied on (NULL in sample). Source type: VARCHAR(100). Category: dimension.';


--
-- Name: COLUMN erp_inv_adjustments_item.reason_category_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.reason_category_id IS 'Reason category id (VARCHAR; NULL in sample). Source type: VARCHAR(100). Category: foreign key.';


--
-- Name: COLUMN erp_inv_adjustments_item.reason_sub_category_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.reason_sub_category_id IS 'Reason sub-category id (VARCHAR; NULL in sample). Source type: VARCHAR(100). Category: foreign key.';


--
