--

COMMENT ON COLUMN public.erp_inv_adjustments_item.integrated_tax IS 'Integrated (IGST) tax on the line. Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_adjustments_item.state_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_adjustments_item.state_tax IS 'State (SGST) tax on the line. Source type: DECIMAL(15,2). Category: measure / financial.';


