CREATE TABLE public.erp_inv_export_details (
    id character varying(200) NOT NULL,
    customer_currency character varying(10),
    exchange_rate numeric(18,10),
    exchange_rate_date timestamp without time zone,
    amount numeric(15,2),
    export_category character varying(10),
    export_type character varying(10),
    customs_reference_number character varying(50),
    customs_reference_type character varying(20),
    customs_reference_date date,
    port_code character varying(10),
    customs_status character varying(20),
    export_status character varying(20),
    sales_tax numeric(15,2),
    discount numeric(15,2),
    shipping_charges numeric(15,2),
    balance numeric(15,2),
    total_payments numeric(15,2),
    pending_payments numeric(15,2),
    state_tax numeric(15,2),
    country_tax numeric(15,2),
    tax_amount numeric(15,2),
    net_amount numeric(15,2),
    gross_amount numeric(15,2),
    additional_charges numeric(15,2),
    created_date timestamp without time zone,
    last_update timestamp without time zone,
    created_user character varying(150),
    updated_user character varying(150)
);


--
-- Name: TABLE erp_inv_export_details; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.erp_inv_export_details IS 'Holds header-level detail for export invoices, capturing export category/type, customs references, exchange rate, balances, and tax, to support export billing, customs, and forex reporting. Notes: Export-invoice counterpart of erp_invoice_details. id is the composite invoice id. exchange_rate varies widely (e.g. 0.0105291775 for USD-priced, 83.25 for INR conversion). export_status sample: INITIATED, COMPLETED; customs_status: PENDING, CLEARED. created_user/updated_user are composite SVID#email. Monetary columns DOUBLE; treat as DECIMAL.';


--
-- Name: COLUMN erp_inv_export_details.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.id IS 'Composite primary key equal to the export invoice id. Source type: VARCHAR(200). Category: composite reference.';


--
-- Name: COLUMN erp_inv_export_details.customer_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.customer_currency IS 'Customer''s transaction currency. Sample: USD. Source type: VARCHAR(10). Category: dimension.';


--
-- Name: COLUMN erp_inv_export_details.exchange_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.exchange_rate IS 'Exchange rate applied. Wide range in sample (0.0105.. to 83.25). Source type: DECIMAL(18,10). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_export_details.exchange_rate_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.exchange_rate_date IS 'Date the exchange rate was set. Source type: TIMESTAMP. Category: timestamp.';


--
-- Name: COLUMN erp_inv_export_details.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.amount IS 'Export invoice amount. Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_export_details.export_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.export_category IS 'Export category. Sample: GOODS. Source type: VARCHAR(10). Category: dimension.';


--
-- Name: COLUMN erp_inv_export_details.export_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.export_type IS 'Export type. Sample: WPAY, WOPAY. Source type: VARCHAR(10). Category: dimension.';


--
-- Name: COLUMN erp_inv_export_details.customs_reference_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.customs_reference_number IS 'Customs reference number (e.g. shipping bill no). Source type: VARCHAR(50). Category: identifier.';


--
-- Name: COLUMN erp_inv_export_details.customs_reference_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.customs_reference_type IS 'Type of customs reference. Sample: SHIPPING_BILL. Source type: VARCHAR(20). Category: dimension.';


--
-- Name: COLUMN erp_inv_export_details.customs_reference_date; Type: COMMENT; Schema: public; Owner: -
--

