--
-- Name: COLUMN erp_inv_export_details.customs_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_details.customs_status IS 'Customs status. Sample: PENDING, CLEARED. Source type: VARCHAR(20). Category: dimension.';


--
-- Name: COLUMN erp_inv_export_details.export_status; Type: COMMENT; Schema: public; Owner: -
