--
-- Name: TABLE erp_inv_export_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.erp_inv_export_items IS 'Holds line-item detail for export invoices in accounts receivable, capturing rate, amount, discounts, and tax components per exported line to support export billing and tax reporting. Notes: Export-invoice counterpart of erp_invoice_items. id is composite beginning with ''#'' (<code>#<invoice_id>, code segment empty in sample). No quantity column. Monetary columns DOUBLE; treat as DECIMAL. Many tax fields NULL; country_tax small (0.05).';


--
-- Name: COLUMN erp_inv_export_items.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_items.id IS 'Composite primary key (<code>#<invoice_id>); begins with ''#'' when the code segment is empty. Source type: VARCHAR(250). Category: composite reference.';


--
-- Name: COLUMN erp_inv_export_items.invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_items.invoice_id IS 'Export invoice id. Joins to erp_invoice_details.id / erp_inv_export_details.id. Source type: VARCHAR(200). Category: foreign key.';


--
-- Name: COLUMN erp_inv_export_items.rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_items.rate IS 'Unit rate of the export line. Source type: DECIMAL(15,2). Category: measure / financial.';


--
-- Name: COLUMN erp_inv_export_items.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_inv_export_items.amount IS 'Export line amount. Source type: DECIMAL(15,2). Category: measure / financial.';


--
