-- Name: erp_invoice_details; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.erp_invoice_details (
    id character varying(200) NOT NULL,
    customer_id character varying(100),
    company_id bigint,
    legal_entity_id bigint,
    invoice_num character varying(50),
    currency_type character varying(50),
    amount numeric(15,2),
    sales_tax numeric(15,2),
    discount numeric(15,2),
    shipping_charges numeric(15,2),
    balance numeric(15,2),
    total_payments numeric(15,2),
    pending_payments numeric(15,2),
    cr_note_amount numeric(15,2),
    dr_note_amount numeric(15,2),
    cr_adjustments numeric(15,2),
    dr_adjustments numeric(15,2),
    due_date timestamp without time zone,
    billing_date timestamp without time zone,
    close_date timestamp without time zone,
    term_code character varying(50),
    term_description character varying(50),
    purchase_order_num character varying(50),
    quotation_num character varying(50),
    first_load_date timestamp without time zone,
    last_load_date timestamp without time zone,
    last_update timestamp without time zone,
    in_collections character varying(5),
    inv_status character varying(10),
    transaction_status character varying(10),
    delete_flag character varying(10),
    archived character varying(10),
    tag_type character varying(30),
    state_tax numeric(15,2),
    country_tax numeric(15,2),
    tds_amount numeric(15,2),
    last_paid_date timestamp without time zone,
    integrated_tax numeric(15,2),
    cess_tax numeric(15,2),
    tax_category character varying(25),
    tax_amount numeric(15,2),
    net_amount numeric(15,2),
    gross_amount numeric(15,2),
    sgstin character varying(15),
    financial_year integer,
    financial_month smallint,
    sequence bigint,
    format_number character varying(50),
    supply_place character varying(3),
    warehouse_id bigint,
    doc_type character varying(25),
    price_type character varying(15),
    additional_charges numeric(15,2),
    forex_gain_loss numeric(15,2),
    source_type character varying(30),
    approval_status character varying(20),
    updated_user character varying(150),
    shared_date timestamp without time zone
);


--
-- Name: TABLE erp_invoice_details; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.erp_invoice_details IS 'Central accounts-receivable invoice header table. Each row captures an invoice''s billed amount, outstanding balance, tax breakdown, payment totals, key dates, and status, and serves as the anchor for almost all invoice, aging, and collection reporting. Notes: Primary anchor table for invoice queries. Composite #-delimited keys are pervasive in the sample data: invoice_id = <invoice_num>#<customer_num>#<company_id>#<legal_entity_id> (e.g. SVINV56118871#20082025#527#1031), customer_id = <customer_num>#<company_id>#<legal_entity_id> (e.g. 20082025#527#1031), and id usually embeds the full invoice_id. These must be parsed before joining and should not be used as clean numeric keys. Monetary columns are DOUBLE in DDL; treat as DECIMAL. Sample shows many literal NULLs, currency INR/USD, inv_status OPEN/CLOSE, transaction_status PAID/OVERDUE, tag_type=''COLLECTION'', tax_category STATE_CENTRAL/NONE, price_type TAX_INCLUSIVE/TAX_EXCLUSIVE; financial_year/financial_month are often NULL. Active = delete_flag=''NO'' AND archived=''NO''; open/overdue = balance > 0.';


--
-- Name: COLUMN erp_invoice_details.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_invoice_details.id IS 'Composite primary key equal to the invoice''s composite invoice_id (invoice_num#customer_num#company_id#legal_entity_id). Referenced as invoice_id by most related tables. Source type: VARCHAR(200). Category: composite reference.';


--
-- Name: COLUMN erp_invoice_details.customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_invoice_details.customer_id IS 'Composite customer isolation key (customer_num#company_id#legal_entity_id). Scope by customer_id = @customer_id. Joins to erp_customer_details.id. Source type: VARCHAR(100). Category: foreign key.';


--
-- Name: COLUMN erp_invoice_details.company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_invoice_details.company_id IS 'Company isolation key. Scope by company_id = @company_id. Sample values e.g. 527, 528. Source type: BIGINT UNSIGNED. Category: foreign key.';


--
-- Name: COLUMN erp_invoice_details.legal_entity_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_invoice_details.legal_entity_id IS 'Legal entity identifier. Joins to d_legalentity.id. Source type: BIGINT UNSIGNED. Category: foreign key.';


--
-- Name: COLUMN erp_invoice_details.invoice_num; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.erp_invoice_details.invoice_num IS 'Business-facing invoice number (the first segment of the composite id). Source type: VARCHAR(50). Category: dimension.';


--
