CREATE TABLE public.sl_erp_invoice_withholding (
    invoice_id character varying(100) NOT NULL,
    company_id bigint,
    legal_entity_id bigint,
    withholding_kind character varying(3),
    wh_group_id bigint,
    wh_section_id bigint,
    taxable_amount numeric(19,4),
    wh_rate_percent numeric(7,4),
    wh_amount numeric(19,4),
    wh_status character varying(20),
    reporting_period character(6),
    notes character varying(255),
    created_date timestamp without time zone,
    created_user character varying(150),
    updated_user character varying(150),
    last_update timestamp without time zone,
    CONSTRAINT ck_sl_erp_invoice_withholding_withholding_kind CHECK (((withholding_kind)::text = ANY ((ARRAY['TDS'::character varying, 'TCS'::character varying])::text[])))
);


--
-- Name: TABLE sl_erp_invoice_withholding; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sl_erp_invoice_withholding IS 'Records withholding tax (TDS/TCS) applied to invoices, capturing taxable amount, rate, withheld amount, status, and reporting period, supporting withholding compliance and return reporting. Notes: Withholding (TDS/TCS) tax per invoice. NO surrogate id column — invoice_id is the key (very long composite, e.g. Zoho-style ids). withholding_kind is ENUM(''TDS'',''TCS''). wh_group_id/wh_section_id and wh_rate_percent are NULL in sample though wh_amount is set. Monetary columns DECIMAL(19,4). reporting_period is YYYYMM (e.g. 202606) — note this is the reverse of gst filing_period (MMYYYY).';


--
-- Name: COLUMN sl_erp_invoice_withholding.invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sl_erp_invoice_withholding.invoice_id IS 'Composite invoice id (very long in sample); acts as the key. Joins to erp_invoice_details.id. Source type: VARCHAR(100). Category: composite reference.';


