--

COMMENT ON COLUMN public.sl_erp_invoice_withholding.withholding_kind IS 'Whether the withholding is TDS or TCS. Sample: TDS. Source type: ENUM(''TDS'',''TCS''). Category: dimension.';


--
-- Name: COLUMN sl_erp_invoice_withholding.wh_group_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sl_erp_invoice_withholding.wh_group_id IS 'Withholding group identifier (NULL in sample). Source type: BIGINT. Category: foreign key.';


--
-- Name: COLUMN sl_erp_invoice_withholding.wh_section_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sl_erp_invoice_withholding.wh_section_id IS 'Withholding section identifier (NULL in sample). Source type: BIGINT. Category: foreign key.';


